    correctKey: 'D',
    explanation: '健康診断の実施は労働安全衛生法上の事業者の義務であり、頻度も法令に定められている。\n【図解】一般健康診断の要点\n　○雇入時健康診断：雇入れの際に実施★\n　○定期健康診断：1年以内ごとに1回★\n　★特定業務従事者（深夜業等）：配置替え時＋6か月以内ごとに1回★\n　⚠実施は法令上の義務（努力目標ではない）\n　×「任意の判断に委ねられる」は誤り',
